'use client';
import React, { useRef, useState } from 'react';

import * as Picker from 'emoji-picker-react/primitives';


// In context: a team chat channel. The picker opens as a popover anchored
// above the composer's emoji button — search with the skin tone control,
// tabs, the grid and a slim preview strip.
export type ShellProps = {
  /** The picker root: Picker.Root, or a styled() wrapper of it. */
  Root?: React.ElementType;
  className?: string;
};

export function Shell({ Root: RootComponent = Picker.Root, className }: ShellProps) {
  const [message, setMessage] = useState('Love the new onboarding flow');
  const [open, setOpen] = useState(true);
  const trigger = useRef<HTMLButtonElement>(null);
  const input = useRef<HTMLInputElement>(null);
  return (
    <div className="chat-window">
      <header className="chat-header">
        <span className="chat-channel"># design-crit</span>
        <span className="chat-members">8 members</span>
      </header>
      <ul className="chat-messages">
        <li className="chat-message">
          <span className="chat-avatar chat-avatar-a" aria-hidden />
          <div>
            <p className="chat-meta">
              <strong>Maya Chen</strong> 10:42 AM
            </p>
            <p>New onboarding flow is up on staging, feedback welcome!</p>
          </div>
        </li>
        <li className="chat-message">
          <span className="chat-avatar chat-avatar-b" aria-hidden />
          <div>
            <p className="chat-meta">
              <strong>Jonah Price</strong> 10:44 AM
            </p>
            <p>The empty states are so much friendlier now.</p>
          </div>
        </li>
      </ul>
      {open && <div className="chat-popover" onKeyDown={(event) => {
        if (event.key === 'Escape') { setOpen(false); trigger.current?.focus(); }
      }}>
        <RootComponent appearance="default" className={className} onEmojiClick={(emoji: Picker.EmojiClickData) => {
          const start = input.current?.selectionStart ?? message.length;
          const end = input.current?.selectionEnd ?? start;
          setMessage(message.slice(0, start) + emoji.emoji + message.slice(end));
          setOpen(false);
          requestAnimationFrame(() => { input.current?.focus(); input.current?.setSelectionRange(start + emoji.emoji.length, start + emoji.emoji.length); });
        }}>
          <Picker.Search />
          <Picker.CategoryNav />
          <Picker.Viewport>
            <Picker.List />
            <Picker.Empty />
          </Picker.Viewport>
          <Picker.Preview />
        </RootComponent>
      </div>}
      <div className="chat-composer">
        <input ref={input} className="chat-input" aria-label="Message #design-crit"
          value={message} onChange={(event) => setMessage(event.target.value)} />
        <div className="chat-tools">
          <button type="button" aria-label="Attach file">＋</button>
          <button ref={trigger} type="button" aria-label="Emoji" aria-expanded={open} className="chat-emoji-button" onClick={() => setOpen(!open)}>
            ☺
          </button>
          <button type="button" className="chat-send">Send</button>
        </div>
      </div>
    </div>
  );
}

/* The host app around the picker (shared by every stack variant). */
.chat-window {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 560px;
  height: 640px;
  overflow: hidden;
  border: 1px solid #e4e4e7;
  border-radius: 14px;
  background: #ffffff;
  color: #18181b;
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  font-size: 14px;
}
.chat-header {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 14px 18px;
  border-bottom: 1px solid #e4e4e7;
}
.chat-channel {
  font-weight: 700;
}
.chat-members {
  color: #52525b;
  font-size: 13px;
}
.chat-messages {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 14px;
  margin: 0;
  padding: 16px 18px;
  list-style: none;
}
.chat-message {
  display: flex;
  gap: 10px;
}
.chat-message p {
  margin: 0;
  line-height: 1.45;
}
.chat-meta {
  color: #52525b;
  font-size: 12px;
}
.chat-meta strong {
  margin-right: 6px;
  color: #18181b;
  font-size: 14px;
}
.chat-avatar {
  width: 34px;
  height: 34px;
  flex: none;
  border-radius: 8px;
}
.chat-avatar-a {
  background: linear-gradient(135deg, #f472b6, #f59e0b);
}
.chat-avatar-b {
  background: linear-gradient(135deg, #60a5fa, #34d399);
}
.chat-popover {
  position: absolute;
  right: 18px;
  bottom: 96px;
  filter: drop-shadow(0 12px 28px rgb(24 24 27 / 18%));
}
.chat-popover::after {
  content: '';
  position: absolute;
  right: 74px;
  bottom: -7px;
  width: 14px;
  height: 14px;
  border-right: 1px solid #e4e4e7;
  border-bottom: 1px solid #e4e4e7;
  background: #ffffff;
  transform: rotate(45deg);
}
.chat-composer {
  margin: 0 18px 18px;
  border: 1px solid #d4d4d8;
  border-radius: 12px;
}
.chat-input {
  box-sizing: border-box;
  width: 100%;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  padding: 12px 14px 4px;
}
.chat-tools {
  display: flex;
  justify-content: flex-end;
  gap: 6px;
  padding: 6px 8px 8px;
}
.chat-tools button {
  min-width: 32px;
  height: 32px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #3f3f46;
  font: inherit;
  font-size: 16px;
}
.chat-tools .chat-emoji-button {
  background: #eef2ff;
  color: #4338ca;
}
.chat-tools .chat-send {
  padding: 0 14px;
  background: #4f46e5;
  color: #ffffff;
  font-size: 14px;
  font-weight: 600;
}

/* Team chat composer — a compact popover: indigo accents, 12px radius,
   slim preview strip. */
.chat-picker {
  --epr-bg-color: #ffffff;
  --epr-text-color: #52525b;
  --epr-highlight-color: #4f46e5;
  --epr-hover-bg-color: #f4f4f5;
  --epr-focus-bg-color: #e0e7ff;
  --epr-picker-border-color: #e4e4e7;
  --epr-search-input-bg-color: #f4f4f5;
  --epr-search-input-bg-color-active: #ffffff;
