  --epr-search-border-color-active: #6366f1;
  --epr-search-input-height: 34px;
  --epr-search-input-border-radius: 8px;
  --epr-search-input-text-color: #18181b;
  --epr-search-input-placeholder-color: #71717a;
  --epr-category-label-bg-color: #fffffff2;
  --epr-category-label-text-color: #52525b;
  --epr-category-label-height: 30px;
  --epr-category-icon-active-color: #4f46e5;
  --epr-category-icon-inactive-color: #71717a;
  --epr-category-navigation-button-size: 20px;
  --epr-preview-height: 46px;
  --epr-preview-emoji-size: 26px;
  --epr-preview-text-color: #18181b;
  --epr-preview-border-color: #e4e4e7;
  --epr-emoji-size: 26px;
  --epr-emoji-padding: 5px;
  --epr-horizontal-padding: 12px;
  width: 340px;
  height: 380px;
  border: 1px solid #e4e4e7;
  border-radius: 12px;
  background: #ffffff;
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
.chat-picker [data-epr-part='search'] > * {
  padding: 12px 12px 4px;
}
.chat-picker [data-epr-part='category-nav'] > * {
  padding: 8px 12px;
}
.chat-picker [data-epr-part='category-tab'][aria-selected='true'] {
  box-shadow: 0 10px 0 -8px #4f46e5;
}
.chat-picker [data-epr-part='category-label'] {
  font-size: 12px;
  font-weight: 600;
  text-transform: none;
}
.chat-picker [data-epr-part='emoji'] {
  border-radius: 8px;
}
.chat-picker [data-epr-part='preview'] {
  font-size: 13px;
}

